```java
public class MaxSum {
    public static int findMaxSum(int a, int b, int[] operations) {
        int maxSum = 0;
        int currentSum = 0;
        int currentA = a;
        int currentB = b;
        int currentOperation = operations[0];

        for (int i = 1; i < operations.length; i++) {
            int nextOperation = operations[i];

            if (nextOperation == currentOperation) {
                currentSum += (currentA * currentB);
                currentA = currentB;
                currentB = currentA;
                currentOperation = operations[i];
            } else {
                currentSum += nextOperation;
                currentA = currentB;
                currentB = currentA;
                currentOperation = nextOperation;
            }
        }

        return currentSum;
    }

